	import { brandList } from "@/api/product";
    export default {
        name: 'c_brand',
        props: {
            configObj: {
                type: Object
            },
            configNme: {
                type: String
            },
            number: {
                type: null
            },
        },
        data () {
            return {
                defaults: {},
                configData: {},
				props: { emitPath: false, multiple: true },
				brandData: []
            }
        },
        mounted () {
            this.$nextTick(() => {
                this.defaults = this.configObj
                this.configData = this.configObj[this.configNme]
				this.getBrandList();
            })
        },
        watch: {
            configObj: {
                handler (nVal, oVal) {
                    this.defaults = nVal
                    this.configData = nVal[this.configNme]
                },
                deep: true
            }
        },
        methods: {
			sliderChange(){
				this.$emit('getConfig',{ name: 'brands'})
			},
			getBrandList(){
			  brandList().then(res=>{
			    this.brandData = res.data
			  }).catch(err=>{
			    this.$Message.error(err.msg);
			  })
			}
        }
    }
